mapper.insert:
            INSERT INTO sale
        	(
        	cstmr_id
        	,shop_id
			,coupon_id
			,ogn_price
			,pay_cash
			,pay_card
			,email
			,phone
			,addr
			,datetime
			,regtime
        	)
        VALUES (
        	(select cstmr_id from cstmr where cstmr_login_id = #{UserID})
        	, #{shopNumber}
        	, #{couponId}
        	, #{ognPrice}
        	, #{payCash}
        	, #{payCard}
        	, #{UserEmail}
        	, #{UserPhone}
        	, #{userAddr}
        	, DATE_FORMAT(now(),'%Y%m%d')
        	, now()
        	);

            SELECT LAST_INSERT_ID();

mapper.select:
SELECT * FROM( SELECT A.sale_id ,(select shop_name from shop where shop_id=A.shop_id) shop_name ,(select cstmr_name from cstmr where cstmr_id=A.cstmr_id) userName ,addr userAddr ,phone userPhone ,datetime ,regtime ,result ,(select sum(prc) from salePrdct where sale_id=A.sale_id) price FROM sale A WHERE datetime between ${startTime} and ${endTime}
and (result = '0000' or result = '0' or result='sucess')
and (result = #{result})
) B
and ( userName = #{cstmrName})
order by datetime desc,regtime desc

select.if:
select datetime ,(select shop_name from shop where shop_id=Y.shop_id) shop_name ,sum(pay_cash) pay_cash ,sum(pay_card) pay_card ,IFNULL(sum(pay_point),0) pay_point ,sum(price) total ,sum(frame_prc) frame_prc ,sum(lens_prc) lens_prc ,sum(clens_prc) clens_prc ,sum(acc_prc) acc_prc
from( SELECT Z.sale_id ,pay_cash ,pay_card ,pay_point ,shop_id ,result ,(select IFNULL(sum(prc),0) from salePrdct where sale_id=Z.sale_id) price ,(select IFNULL(sum(prc),0) from salePrdct A, prdct B where A.prdct_id = B.prdct_id and A.sale_id=Z.sale_id ) frame_prc ,(select IFNULL(sum(prc),0) from salePrdct A, lens B where A.prdct_id = B.prdct_id and A.sale_id=Z.sale_id ) lens_prc ,(select IFNULL(sum(prc),0) from salePrdct A, clens B where A.prdct_id = B.prdct_id and A.sale_id=Z.sale_id ) clens_prc ,(select IFNULL(sum(prc),0) from salePrdct A, clens_acc B where A.prdct_id = B.prdct_id and A.sale_id=Z.sale_id ) acc_prc ,datetime FROM sale Z WHERE (select replace(datetime ,".","")from sale_off where sale_id = Z.sale_id) between ${startTime} and ${endTime}
AND shop_id = #{shopId}
AND (result = '0000' OR result='success')
) Y
group by datetime
group by shop_name

mapper.update:
UPDATE sale SET
	result		= #{CJSResultCode}
	,result_msg = #{CJSResultMessage}
	,pay_id		= #{CJSPayID}
	,trade_id	= #{CJSTradeID}
	,pay_date	= #{CJSPaydate}
	,pgctrl		= #{Crd_pgctrl_Cd_p}
WHERE
	sale_id 			= #{saleId}

mapper.select:
SELECT F.sale_id ,J.job_id ,F.cstmr_id ,C.cstmr_name ,C.cstmr_cd ,J.ty_cd ,sum(if(J.card_ty=13,J.pay_card+J.pay_cash,J.pay_cash) )as pay_cash ,sum(if(J.card_ty=13,0,J.pay_card) )as pay_card ,J.pay_point ,J.card_ty ,(select card_com_name from card_com_info where card_com_id = J.card_ty) as card_name ,F.cancel ,if(F.shop_id>70, F.shop_id, (select shop_num from shop where shop_num=F.shop_id)) as shop_id ,if(F.shop_id>70, (select shop_name from shop where shop_id = F.shop_id), (select shop_name from shop where shop_num=F.shop_id)) as shop_name ,ogn_price ,dscnt_price ,partner_dscnt ,partner_id ,etc_dscnt ,etc_dscnt_memo ,result ,F.datetime ,hist_id ,earn_prcnt ,coupon_birth ,point_fmly_cd ,F.tax_bigo FROM sale_off F INNER JOIN cstmr C INNER JOIN sale_job_off J ON C.cstmr_id = F.cstmr_id and F.sale_id = J.sale_id
C.cstmr_cd =#{sale.cstmrCd}
and J.datetime >= #{sDate} and J.datetime <= #{eDate} and J.ty_cd = '01200004' and F.cancel = 0 and (J.pay_card != 0 or J.pay_cash != 0 )
group by F.sale_id order by F.sale_id ;

mapper.update:
UPDATE sale_off SET
	tax_bigo = #{taxBigo}
WHERE
	sale_id = #{saleId}
